КаталогEDT = Объект.КаталогСтруктурыТекущейБазы;

Результат = "=== КОРЕНЬ EDT-ПРОЕКТА ===" + Символы.ПС;
Результат = Результат + "Путь: " + КаталогEDT + Символы.ПС + Символы.ПС;

КорневойКаталог = Новый Файл(КаталогEDT);
Если НЕ КорневойКаталог.Существует() Тогда
	Результат = Результат + "ОШИБКА: Корневой каталог не найден!" + Символы.ПС;
Иначе
	Содержимое = НайтиФайлы(КаталогEDT, "*.*", Ложь);
	Для Каждого Файл Из Содержимое Цикл
		Если Файл.ЭтоКаталог() Тогда
			Результат = Результат + "[DIR]  " + Файл.Имя + "/" + Символы.ПС;
		Иначе
			Результат = Результат + "[FILE] " + Файл.Имя + Символы.ПС;
		КонецЕсли;
	КонецЦикла;

	ПутьDP = КаталогEDT + "DataProcessors/";
	ФайлDP = Новый Файл(ПутьDP);
	Если ФайлDP.Существует() Тогда
		Результат = Результат + Символы.ПС + "=== DataProcessors/ ===" + Символы.ПС;
		КаталогиDP = НайтиФайлы(ПутьDP, "*", Ложь);
		Для Каждого Файл Из КаталогиDP Цикл
			Если Файл.ЭтоКаталог() Тогда
				Результат = Результат + "[DIR]  " + Файл.Имя + "/" + Символы.ПС;
			Иначе
				Результат = Результат + "[FILE] " + Файл.Имя + Символы.ПС;
			КонецЕсли;
		КонецЦикла;

		ПутьExt = ПутьDP + "ExtCntrl/";
		ФайлExt = Новый Файл(ПутьExt);
		Если ФайлExt.Существует() Тогда
			Результат = Результат + Символы.ПС + "=== DataProcessors/ExtCntrl/ ===" + Символы.ПС;
			ВсеФайлы = НайтиФайлы(ПутьExt, "*.*", Истина);
			Для Каждого Файл Из ВсеФайлы Цикл
				Отн = СтрЗаменить(Файл.ПолноеИмя, ПутьExt, "");
				Если Файл.ЭтоКаталог() Тогда
					Результат = Результат + "[DIR]  " + Отн + "/" + Символы.ПС;
				Иначе
					Результат = Результат + "[FILE] " + Отн + " (" + Файл.Размер() + ")" + Символы.ПС;
				КонецЕсли;
			КонецЦикла;
		Иначе
			Результат = Результат + Символы.ПС + "ExtCntrl не найден в DataProcessors/" + Символы.ПС;
		КонецЕсли;
	Иначе
		Результат = Результат + Символы.ПС + "Каталог DataProcessors/ не найден" + Символы.ПС;
	КонецЕсли;
КонецЕсли;
